package shop

import (
	"encoding/json"
	"net/http"
)

// healthResponse represents the response structure for the health check endpoint.
type healthResponse struct {
	Data map[string]int `json:"data"`
}

// healthRoutes registers the GET /healthz endpoint.
func (s *Server) healthRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /healthz", s.handleHealth)
}

// handleHealth responds with a 200 status and a JSON payload indicating the count of stored items for each resource.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	// Get the number of users stored.
	usersCount := len(s.users.List())

	// Get the number of products stored.
	productsCount := len(s.products.List())

	// Get the number of orders stored.
	ordersCount := len(s.orders.List())

	// Create the response data.
	responseData := map[string]int{
		"users":     usersCount,
		"products":  productsCount,
		"orders":    ordersCount,
	}

	// Encode the response.
	writeJSON(w, http.StatusOK, healthResponse{Data: responseData})
}

