func (st *OrderStore) Create(o Order) Order {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	o.ID = formatID("ord", st.seq)
	o.Items = slices.Clone(o.Items)
	st.items[o.ID] = o
	return o
}

func (st *OrderStore) Get(id string) (Order, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	o, ok := st.items[id]
	return o, ok
}

